export function applyOwnerOnlyToolPolicy(
  tools: AnyAgentTool[],
  senderIsOwner: boolean,
  bypassOwnerOnlyTools?: string[],
) {
  const bypassSet = new Set(
    (bypassOwnerOnlyTools ?? []).map((name) => normalizeToolName(name)),
  );
  const withGuard = tools.map((tool) => {
    if (!isOwnerOnlyTool(tool)) {
      return tool;
    }
    // Tools explicitly listed in alsoAllow bypass the owner-only restriction
    // but still get wrapped with the owner-guard so execution is rejected
    // for non-owners (unless alsoAllow overrides that separately).
    if (bypassSet.has(normalizeToolName(tool.name))) {
      return wrapOwnerOnlyToolExecution(tool, true);
    }
    return wrapOwnerOnlyToolExecution(tool, senderIsOwner);
  });
  if (senderIsOwner) {
    return withGuard;
  }
  // When sender is not owner, keep only non-owner-only tools.
  // Owner-only tools are already wrapped with senderIsOwner=false
  // by this point — they will throw at execution time.
  // Exception: tools in bypassOwnerOnlyTools were wrapped with senderIsOwner=true
  // so they survive the filter.
  return withGuard.filter((tool) => !isOwnerOnlyTool(tool));
}

