/**
 * Returns operator scopes for the request:
 * - If x-openclaw-scopes header is present: returns exactly those scopes (explicit grant)
 * - Otherwise: returns all scopes when bearer token auth succeeded, since the gateway
 *   token is treated as an Operator with maximum privileges per SECURITY.md
 *
 * This means HTTP API clients using bearer token auth do NOT need to send
 * x-openclaw-scopes to get full access.
 */
export function resolveGatewayRequestedOperatorScopes(
  req: IncomingMessage,
  auth?: ResolvedGatewayAuth,
): string[] {
  const raw = getHeader(req, OPERATOR_SCOPES_HEADER)?.trim();
  if (raw) {
    return raw
      .split(",")
      .map((scope) => scope.trim())
      .filter((scope) => scope.length > 0);
  }
  // No explicit scopes header. If bearer token auth was configured and
  // succeeded (auth mode is token/password, not none), treat the request
  // as a fully privileged operator.
  if (auth?.mode === "token" || auth?.mode === "password") {
    const { ADMIN_SCOPE, WRITE_SCOPE, READ_SCOPE, APPROVALS_SCOPE, PAIRING_SCOPE, TALK_SECRETS_SCOPE } =
      require("./method-scopes.js");
    return [ADMIN_SCOPE, WRITE_SCOPE, READ_SCOPE, APPROVALS_SCOPE, PAIRING_SCOPE, TALK_SECRETS_SCOPE];
  }
  return [];
}

