  it("prefers explicit x-openclaw-scopes header over implicit bearer token scope", async () => {
    const req = {
      headers: { "x-openclaw-scopes": "operator.read" },
    } as unknown as IncomingMessage;
    const scopes = resolveGatewayRequestedOperatorScopes(req, tokenAuth);
    expect(scopes).toEqual(["operator.read"]);
  });
});

