  const baseUrl = getOllamaBaseUrl(config);
  // Wrap in AbortController timeout to prevent infinite hang during model switch.
  // If the Ollama provider does not connect/respond within 30s, treat as unavailable.
  const timeoutMs = 30_000;
  const ac = new AbortController();
  const timeout = setTimeout(() => ac.abort(), timeoutMs);
  try {
    return ollamaProvider({ baseUrl, signal: ac.signal });
  } finally {
    clearTimeout(timeout);
  }
},

