// Proposed fix for OpenClaw chat desynchronization issue
// This code ensures message input is always synchronized with displayed chat

class ChatSyncManager {
  constructor() {
    this.currentSessionId = null;
    this.displayedSessionId = null;
    this.pendingSwitch = false;
    this.inputLocked = false;
  }

  // Call when switching chats
  async switchChat(newSessionId) {
    // Lock input immediately
    this.lockInput();
    this.pendingSwitch = true;

    try {
      // Update current session
      this.currentSessionId = newSessionId;

      // Load chat messages
      await this.loadChatMessages(newSessionId);

      // Verify synchronization
      if (this.verifySynchronization()) {
        this.displayedSessionId = newSessionId;
        this.pendingSwitch = false;

        // Add visual indicator
        this.updateSessionIndicator(newSessionId);

        // Unlock after small delay to ensure UI updates
        setTimeout(() => this.unlockInput(), 100);
      } else {
        throw new Error('Chat synchronization failed');
      }
    } catch (error) {
      console.error('Chat switch failed:', error);
      // Revert to previous session
      await this.revertToPreviousSession();
    }
  }

  // Validate before sending message
  canSendMessage() {
    if (this.inputLocked) {
      console.warn('Input is locked during chat switch');
      return false;
    }

    if (this.pendingSwitch) {
      console.warn('Chat switch in progress');
      return false;
    }

    if (this.currentSessionId !== this.displayedSessionId) {
      console.error('CRITICAL: Session mismatch detected!', {
        current: this.currentSessionId,
        displayed: this.displayedSessionId
      });
      this.showSyncError();
      return false;
    }

    return true;
  }

  // Add to message send handler
  async sendMessage(message) {
    if (!this.canSendMessage()) {
      return false;
    }

    // Double-check session ID in request
    const sessionCheck = {
      sessionId: this.currentSessionId,
      displayedSessionId: this.displayedSessionId,
      timestamp: Date.now()
    };

    // Include session validation in API call
    return await api.sendMessage({
      message,
      sessionId: this.currentSessionId,
      validationToken: this.generateValidationToken(sessionCheck)
    });
  }

  // Visual indicators
  updateSessionIndicator(sessionId) {
    const indicator = document.querySelector('.session-indicator');
    if (indicator) {
      indicator.textContent = `Active: ${sessionId}`;
      indicator.classList.add('synced');
      indicator.classList.remove('desynced');
    }
  }

  showSyncError() {
    const indicator = document.querySelector('.session-indicator');
    if (indicator) {
      indicator.textContent = 'SYNC ERROR - DO NOT SEND';
      indicator.classList.add('desynced');
      indicator.classList.remove('synced');
    }

    // Disable input
    this.lockInput();

    // Show alert
    alert('Chat synchronization error detected. Please refresh the page.');
  }

  lockInput() {
    this.inputLocked = true;
    const input = document.querySelector('.message-input');
    if (input) {
      input.disabled = true;
      input.placeholder = 'Switching chats...';
    }
  }

  unlockInput() {
    this.inputLocked = false;
    const input = document.querySelector('.message-input');
    if (input) {
      input.disabled = false;
      input.placeholder = 'Type a message...';
    }
  }

  verifySynchronization() {
    // Check that all UI elements show same session
    const chatHeader = document.querySelector('.chat-header')?.dataset.sessionId;
    const messageContainer = document.querySelector('.messages')?.dataset.sessionId;
    const inputField = document.querySelector('.message-input')?.dataset.sessionId;

    return chatHeader === this.currentSessionId && 
           messageContainer === this.currentSessionId &&
           inputField === this.currentSessionId;
  }

  generateValidationToken(data) {
    // Simple token to ensure request matches UI state
    return btoa(JSON.stringify(data));
  }
}

// CSS for visual indicators
const syncStyles = `
.session-indicator {
  padding: 4px 8px;
  font-size: 12px;
  position: absolute;
  top: 5px;
  right: 5px;
  border-radius: 4px;
  transition: all 0.3s;
}

.session-indicator.synced {
  background: #4caf50;
  color: white;
}

.session-indicator.desynced {
  background: #f44336;
  color: white;
  font-weight: bold;
  animation: pulse 1s infinite;
}

@keyframes pulse {
  0% { opacity: 1; }
  50% { opacity: 0.5; }
  100% { opacity: 1; }
}

.message-input:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}
`;
